function rf_native_assert_transactions(){
 global $wpdb;static $ready=false;if($ready)return;$need=[$wpdb->posts,$wpdb->postmeta,$wpdb->term_relationships,$wpdb->prefix.'icl_translations',$wpdb->prefix.'wc_product_attributes_lookup',$wpdb->prefix.'wc_product_meta_lookup'];$tables=$wpdb->get_results('SHOW TABLE STATUS',ARRAY_A);foreach($need as $name){$rows=array_values(array_filter($tables,fn($t)=>$t['Name']===$name));if(count($rows)!==1||strtolower($rows[0]['Engine'])!=='innodb')throw new RuntimeException('Нет транзакций:'.$name);}$ready=true;
}
function rf_native_snapshot($id){
