 return ['posts'=>$wpdb->get_results("SELECT * FROM {$wpdb->posts} WHERE ID IN ($in) ORDER BY ID",ARRAY_A),'meta'=>$wpdb->get_results("SELECT * FROM {$wpdb->postmeta} WHERE post_id IN ($in) ORDER BY meta_id",ARRAY_A),'relations'=>$wpdb->get_results("SELECT * FROM {$wpdb->term_relationships} WHERE object_id IN ($in) ORDER BY object_id,term_taxonomy_id",ARRAY_A),'wpml'=>$wpdb->get_results("SELECT * FROM {$wpdb->prefix}icl_translations WHERE element_type IN ('post_product','post_product_variation') AND element_id IN ($in) ORDER BY translation_id",ARRAY_A),'prices'=>$wpdb->get_results("SELECT * FROM {$wpdb->prefix}wc_product_meta_lookup WHERE product_id IN ($in) ORDER BY product_id",ARRAY_A)];
}
function rf_native_clear($id){global $wpdb;$ids=$wpdb->get_col($wpdb->prepare("SELECT ID FROM {$wpdb->posts} WHERE post_parent=%d AND post_type='product_variation'",$id));$ids[]=$id;foreach($ids as $pid){clean_post_cache((int)$pid);wp_cache_delete((int)$pid,'post_meta');WC_Cache_Helper::invalidate_cache_group('product_'.$pid);}clean_object_term_cache($id,'product');wc_delete_product_transients($id);}
function rf_native_missing_translation($spec,$directory){
 global $wpdb;$source=$spec['source'];$lang=$spec['target_lang'];$tax=$source['taxonomy'];$type='tax_'.$tax;$current=rf_import_raw_term($tax,'term_id',(int)$source['term_id']);if(!$current||!$current['trid']||$current['trid']!=$source['trid'])throw new RuntimeException('Изменилась группа исходного термина');
 $rows=$wpdb->get_results($wpdb->prepare("SELECT element_id FROM {$wpdb->prefix}icl_translations WHERE element_type=%s AND trid=%d AND language_code=%s",$type,$source['trid'],$lang));if(count($rows)===1)return;if($rows)throw new RuntimeException('Неоднозначный перевод');
 $slug=sanitize_title($source['name']).'-rf-native-'.$source['term_id'].'-'.$lang;
