 $before=['source'=>$current,'translations'=>$wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}icl_translations WHERE element_type=%s AND trid=%d",$type,$source['trid']),ARRAY_A)];file_put_contents($directory.'/term-'.$source['term_id'].'-'.$lang.'-before.json',json_encode($before,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));
