 $original=$wpdb->get_var($wpdb->prepare("SELECT language_code FROM {$wpdb->prefix}icl_translations WHERE element_type=%s AND trid=%d AND source_language_code IS NULL LIMIT 1",$type,$source['trid']));if(!$original)$original=$source['lang'];
 do_action('wpml_set_element_language_details',['element_id'=>(int)$created['term_taxonomy_id'],'element_type'=>$type,'trid'=>(int)$source['trid'],'language_code'=>$lang,'source_language_code'=>$original,'check_duplicates'=>true]);
 $term=rf_import_raw_term($tax,'term_id',(int)$created['term_id']);if(!$term||$term['lang']!==$lang||$term['trid']!=$source['trid']||$term['name']!==$source['name'])throw new RuntimeException('Не сохранился перевод термина');file_put_contents($directory.'/term-'.$source['term_id'].'-'.$lang.'-created.json',json_encode($term,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));
}
function rf_native_apply($plan,$directory,$inject_failure=false,$include_trash=false,$preserve_untouched_issues=false){
 global $wpdb;rf_native_assert_transactions();$id=(int)$plan['product']['ID'];$lang=$plan['product']['lang'];$statuses=['publish','draft','pending','private','future'];if($include_trash)$statuses[]='trash';if(!in_array(get_post_status($id),$statuses,true))throw new RuntimeException('Карточка больше не активна');foreach($plan['issues'] as $issue)if(in_array($issue['kind'],['missing_translation','unknown_term_or_product_language'],true))throw new RuntimeException('Нужен новый план после подготовки словаря');
