 foreach($plan['changes'] as $change){$found=false;foreach($expected['meta'] as &$m){if((int)$m['meta_id']!==$change['meta_id'])continue;if((int)$m['post_id']!==$change['post_id']||$m['meta_key']!==$change['key']||$m['meta_value']!==$change['before'])throw new RuntimeException('Вариант изменился после плана');$m['meta_value']=$change['after'];$found=true;}unset($m);if(!$found)throw new RuntimeException('Не найден исходный атрибут');if(1!==$wpdb->update($wpdb->postmeta,['meta_value'=>$change['after']],['meta_id'=>$change['meta_id'],'meta_value'=>$change['before']]))throw new RuntimeException('Атрибут не обновлён');}
