 foreach($plan['wanted_terms'] as $tax=>$terms){$old=$wpdb->get_results($wpdb->prepare("SELECT r.* FROM {$wpdb->term_relationships} r JOIN {$wpdb->term_taxonomy} tt USING(term_taxonomy_id) WHERE r.object_id=%d AND tt.taxonomy=%s",$id,$tax),ARRAY_A);$old_ids=array_column($old,'term_taxonomy_id');$orders=array_column($old,'term_order','term_taxonomy_id');$expected['relations']=array_values(array_filter($expected['relations'],fn($r)=>!((int)$r['object_id']===$id&&in_array($r['term_taxonomy_id'],$old_ids,true))));$wpdb->query($wpdb->prepare("DELETE r FROM {$wpdb->term_relationships} r JOIN {$wpdb->term_taxonomy} tt USING(term_taxonomy_id) WHERE r.object_id=%d AND tt.taxonomy=%s",$id,$tax));foreach($terms as $term){$tt=(int)$term['term_taxonomy_id'];$raw=rf_import_raw_term($tax,'term_id',(int)$term['term_id']);if(!$raw||$raw['term_taxonomy_id']!=$tt||($raw['lang']!==$lang&&!($preserve_untouched_issues&&in_array((string)$tt,$old_ids,true))))throw new RuntimeException('Изменился язык термина');$order=(int)($orders[$tt]??0);if(false===$wpdb->insert($wpdb->term_relationships,['object_id'=>$id,'term_taxonomy_id'=>$tt,'term_order'=>$order]))throw new RuntimeException('Не сохранена связь');$expected['relations'][]=['object_id'=>(string)$id,'term_taxonomy_id'=>(string)$tt,'term_order'=>(string)$order];}}
