 }catch(Throwable $e){if($active)$wpdb->query('ROLLBACK');rf_native_clear($id);throw $e;}finally{$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',$lock));}
}
// Чтение WooCommerce не должно пересохранять заголовки вариаций во время индексации.
